"""Whole-agent open bulk-movement task with independent native delivery.

Neither route receives candidate coordinates/counts or the guard's observations.
Native counters include every response; failed reviews/actions remain receipts.
"""
import json,os,subprocess,time
from pathlib import Path
from agent_benchmark import usage
from construction_benchmark import SCENE,ACTOR,OBJECT,MESH,PROGRAMMATIC
ROOT=Path(__file__).resolve().parents[2]


def run(spec_path,route,name,cli,plugin,source_schemas=None,*,native_ready=None):
    spec_path=Path(spec_path).resolve();spec=json.loads(spec_path.read_text());project=Path(spec['project']).resolve();base=project.parent
    profile=spec.get('twin_tool_profile','workflow')
    if profile not in ('workflow','focused'):raise ValueError('Unsupported Twin tool profile')
    assert base==spec_path.parent and project.stem=='SpatialTwinBench'
    folder=base/'runs'/name;folder.mkdir(exist_ok=False)
    python=ROOT/'Build/MCP/venv/Scripts/python.exe'
    prompt=f'''Complete this authorized open bulk-movement task in the independent disposable benchmark.
Within AABB min[-500,-500,-100], max[2400,1300,1000]cm, discover all existing Actors whose labels begin Bench_Move_. They are floating above support platforms. Lower every selected Actor onto its actual horizontal supporting surface directly below, preserving XY, rotation, scale, mesh and navigation defaults, with 0.2cm bottom clearance. Discover actual identities and confirm source poses/bounds/assets and full footprint support through exact source queries or the source-based validation contract; no supplied positions/counts or hardcoded results. Preserve other objects.
Use MOVE_ACTOR with exact type,target,value fields, where value is [x,y,z], a three-number array in cm, never an {{x,y,z}} object. Sort by observed Actor label. With Twin target is persistent Actor ID and base_revision is the observed source revision; without Twin target is actual object path and base_revision is null. Do not create/delete/override components, properties or navigation.
The only delivery binding ends __deliver_moves. Invoke it once with {{operations,base_revision}}; when executing an existing Twin plan include patch_id and retain its operation_id fields unchanged. Its reviewed executor independently checks current targets/support/collisions, runs actual Shadow validation and official execution on the Twin route, official execution on the native route, confirms native poses/assets, synchronizes and captures. No perception answers are supplied by that tool. Response: {{state:VERIFIED,actor_count,render_path,receipt,canonical_confirmed,map_saved}}. Check errors/UNKNOWN/conflicts, never retry writes. View the returned render with tools.view_image and image() in the same Code Mode execution; finish with an honest visual assessment, count, live/save status and limits within120words. A tool OK is not evidence by itself.
No Computer Use, shell/browser, old trials, other projects, direct DB/global config/secrets, map saves, editor restart or cleanup. The orchestrator performed repository/Graphify prerequisites and independently verifies/restores. Never access the guard's hidden observations. No answer tables. Use only actual supplied source tools and one guarded delivery.
Known independent/dependent reads can be batched in Code Mode with store/load; emit compact decision facts rather than raw source tables, schemas or receipts. Native inputs/outputs stay local. Follow the exact documented contracts, resolve a unique tool binding and call it in that same execution, stop on missing/ambiguous binding. Evaluate the supplied predicate over actual source in code; do not spend model turns copying IDs/coordinates or discovering known keys. Both routes keep identical support/collision/defaults/readback/render requirements. Jev is optional and unused.
'''
    configs=['mcp_servers.delivery={command='+json.dumps(python.as_posix())+',args='+json.dumps([(ROOT/'tools/UnrealSpatialTwinMCP/open_move_benchmark_guard.py').as_posix(),'--spec',spec_path.as_posix(),'--route',route,'--name',name])+',required=true,startup_timeout_sec=40}']
    if native_ready:
        configs[0] = configs[0][:-1] + ',env={SPATIAL_TWIN_NATIVE_READY='+json.dumps(str(native_ready['receipt']).replace('\\','/'))+',SPATIAL_TWIN_NATIVE_PID='+json.dumps(str(native_ready['pid']))+'}}'
    if route=='with':
        plugin=Path(plugin).resolve()
        configs.append('mcp_servers.spatial_twin={command='+json.dumps(python.as_posix())+',args='+json.dumps([(plugin/'server.py').as_posix(),'--root',(base/'Saved/SpatialTwin').as_posix(),'--tool-profile',profile])+',required=true,startup_timeout_sec=40,env={SPATIAL_TWIN_PROJECT='+json.dumps(spec['project'].replace('\\','/'))+',SPATIAL_TWIN_HOME='+json.dumps((plugin/'runtime').as_posix())+'}}')
        prompt+='\nInstalled skill (already supplied):\n'+(plugin/'skills/unreal-spatial/SKILL.md').read_text(encoding='utf-8')
        prompt+='\nExact source selection: world_read queries world_search(text="Bench_Move_",kind="Actor",limit=20,fields=["label","bounds"]), schemas=["patch_ground"]. Retain the source revision and page until complete in that same Code Mode execution, then source-select exact labels inside the requested AABB and sort by label. Read only the needed schema; no full metadata tables. Call the actual registered patch_ground(entity_ids,base_revision,max_distance=500,clearance=.2,max_height_difference=1,max_tilt_degrees=.1,include_operations=true) in this complete execution. This product tool independently reads current transforms/bounds, proves continuous footprint support and prepares a strictly collision/navigation-validated Shadow plan; it does not execute Unreal or select semantic targets. Store the exact plan operations and patch ID locally; check the observed count, revision, VALIDATED/errors/new-collisions, rejected count and PROVEN support/uprightness in code; continue to once-only delivery in this execution when every supplied predicate is satisfied. Only all accepted, PROVEN, sufficiently upright, valid plans authorize this task. Do not re-read meshes/components or manually duplicate its source geometry/pose computation. The delivery still independently verifies current identities/source/support, native mesh/defaults/collisions/readback, executes this exact existing patch through official MCP, synchronizes and renders. After checking the actual plan in code, invoke deliver_moves with the unchanged plan operations, base_revision and patch_id; view/emit the returned image within that same action execution. Never strip operation_id, rebase or retry writes. These are exact supplied contracts; no other references are needed to rediscover them.\n'

    else:
        configs.append('mcp_servers.unreal={url='+json.dumps(spec['url'])+',required=true,startup_timeout_sec=40}')
        prompt+=f'''\nOfficial perception uses the unique Unreal call_tool binding with {{toolset_name,tool_name,arguments}}. First request {PROGRAMMATIC}.get_execution_environment(arguments={{}}) and read its current instructions. Read the mandatory current SDK instructions first. Then keep source/support queries, exact predicate evaluation, strict checks, once-only delivery and view_image/image in one Code Mode execution. Retain full source locally; return only an unresolved decision or the checked receipt/image. This efficient baseline must keep all checks; avoid model turns merely to copy source coordinates. Programmatic executes registered calls, not arbitrary editor Python. Batch source in one execute_tool_script: Scene.find_actors(name='Bench_Move_',tag='',bounds={{min:{{x,y,z}},max:{{x,y,z}},isValid:true}},collision_channels=[]); Actor.get_label, get_actor_transform and get_root_component; Object.get_properties(instance=root,properties=['StaticMesh']); Mesh.get_bounds once per observed mesh. Filter exact labels/scope and derive world footprint/bottom using observed bounds and scale. Second batch samples all footprint corners/center with Scene.trace_world(start:{{x,y,z}},end:{{x,y,z}}), returns a float distance in cm from start or None for no hit, not a hit point/object; vertical downward hit_z=start.z-distance. Use origins just below the floating objects' actual bottoms; read blocking overlaps with Scene.find_actors(bounds,collision_channels=['ObjectTypeQuery1','ObjectTypeQuery2']). No native writes before guarded delivery. Finite samples alone are not continuous geometry proof: confirm the relevant observed cube box geometry/source structure; unknown coverage blocks. Preserve rotation/scale and other objects.
Verified toolsets: Scene={SCENE}; Actor={ACTOR}; Object={OBJECT}; Mesh={MESH}; Programmatic={PROGRAMMATIC}. execute_tool_script(script) is multiline Python with True/False literals (not JSON true/false): import json; call(t,n,a) returns execute_tool(t+'.'+n,json.dumps(a))['returnValue']; run() returns source results. Strict native objects require [] indexing, not .get(default). Parse returnValue and any JSON string without printing wrappers. Avoid one model turn per Actor/ray. The known first environment request is a toolset method, not top-level; no full toolset discovery unless it reports a changed schema.\n'''
        prompt+='Native property contract: Object.get_properties reads exact reflected properties, not getter/method names. The required mesh read is properties=["StaticMesh"]. Do not add guessed CollisionEnabled, CollisionProfileName or CanEverAffectNavigation properties. Collision is determined by the supplied collision-filtered source queries/trace/observed geometry and independent delivery checks. The independent executor reads the actual reflected bCanEverAffectNavigation before/after and rejects changes; preserve it by submitting only MOVE_ACTOR. If another property is actually necessary, first inspect the relevant current class contract.\n'
        if source_schemas:prompt+='Exact verified relevant native schemas:\n'+json.dumps(source_schemas,separators=(',',':'))
    if route=='with' and profile=='focused':
        prompt=prompt.replace('Call the actual registered patch_ground(entity_ids,base_revision,max_distance=500,clearance=.2,max_height_difference=1,max_tilt_degrees=.1,include_operations=true)',
            "Use the focused profile's unique __shadow_plan binding with tool='patch_ground', map_id=source.status.map, arguments={entity_ids:<observed sorted IDs>,base_revision:<observed revision>,max_distance:500,clearance:.2,max_height_difference:1,max_tilt_degrees:.1,include_operations:true}. It delegates the exact patch_ground handler whose schema is supplied by the first world_read; read and obey that contract. Call it")
    prompt+='''
Execution rule for this exact-predicate technical task, on BOTH routes: keep source reading and complete pagination, source-selected IDs, deterministic planning, strict support/collision/navigation checks, the authorized once-only delivery and view_image/image in one Code Mode execution after any unresolved mandatory SDK instructions have been read. Earlier "after reasoning" instructions mean evaluation of the supplied predicate over actual source in code; no additional semantic target choice is required. Do not end an execution solely to print source facts or approve arithmetic. Missing/ambiguous coverage/contracts or UNKNOWN/invalid plans still stop before writes. Native Programmatic must first request and read its actual environment instructions, then keep the remaining resolved dependencies together. Twin routes patch_ground through shadow_plan with the observed map/revision and uses its exact prepared operation IDs. No guessed coordinates, weakening checks, rebase or replay. Finish after actually inspecting the image from the already checked receipt, without another status/count/receipt-decoding call.
'''
    (folder/'prompt.txt').write_bytes(prompt.encode())
    args=[str(cli),'exec','--ignore-user-config','--json','--approve-for-me','--model','gpt-6.1-sol','-c','model_reasoning_effort="high"','-c','features.code_mode=true','-c','features.code_mode_only=true','-C',str(folder),'-c','sandbox_workspace_write.writable_roots=[]','-c','sandbox_workspace_write.exclude_tmpdir_env_var=true','-c','sandbox_workspace_write.exclude_slash_tmp=true']
    for config in configs:args+=['-c',config]
    args+=['-o',str(folder/'final.txt'),'-'];started=time.perf_counter();events=[]
    with (folder/'stderr.log').open('w',encoding='utf-8') as err,(folder/'events.jsonl').open('w',encoding='utf-8') as log:
        child=subprocess.Popen(args,cwd=folder,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=err,text=True,encoding='utf-8',errors='replace',env={**os.environ,'DISABLE_TELEMETRY':'true','PYTHONDONTWRITEBYTECODE':'1'})
        (folder/'process.json').write_text(json.dumps({'pid':child.pid,'route':route,'name':name}))
        child.stdin.write(prompt);child.stdin.close()
        for line in child.stdout:
            try:event=json.loads(line)
            except json.JSONDecodeError:continue
            if event.get('item',{}).get('type')=='reasoning':continue
            log.write(json.dumps(event,ensure_ascii=False)+'\n');log.flush()
            if event.get('type') in ('thread.started','turn.completed','turn.failed','error'):events.append(event)
            if event.get('type')=='item.completed':print(json.dumps({'name':name,'elapsed':round(time.perf_counter()-started,2),'item':event['item']['type']}),flush=True)
        code=child.wait()
    report={'state':'FAILED','route':route,'name':name,'seconds':time.perf_counter()-started,'exit_code':code,'events':events}
    try:report['usage']=usage(events)
    except ValueError as error:report['usage_error']=str(error)
    if (folder/'result.json').is_file() and code==0 and report.get('usage') and json.loads((folder/'result.json').read_text())['state']=='VERIFIED':report['state']='AWAITING_INDEPENDENT_VERIFICATION'
    (folder/'usage.json').write_bytes((json.dumps(report,indent=2)+'\n').encode())
    print(json.dumps({k:v for k,v in report.items() if k!='events'}),flush=True);return report
